// Model IDs used by the earlier three-model comparison.
export const EARLIER_MODEL_IDS = ['public-service', 'global-employer', 'mixed'];

const SOURCES = [
  ['https://ijdesign.org/index.php/IJDesign/article/view/1480/589', 'Hassenzahl and colleagues on designing for meaningful everyday moments (2013)'],
  ['https://pubmed.ncbi.nlm.nih.gov/15576620/', 'Kahneman and colleagues’ Day Reconstruction Method (2004)'],
  ['https://hdr.undp.org/system/files/documents/primercomplete.pdf', 'UNDP primer on the capabilities approach'],
  ['https://transitiondesigninstitute.net/', 'Transition Design Institute on working back from desired futures'],
  ['https://www.nobelprize.org/prizes/economic-sciences/2009/ostrom/lecture/', 'Elinor Ostrom’s Nobel lecture on governing shared resources'],
  ['https://compdemocracy.org/faq/', 'Polis FAQ, including what opinion mapping does not do'],
  ['https://darioamodei.com/essay/machines-of-loving-grace', 'Dario Amodei’s Machines of Loving Grace, an optimistic scenario rather than evidence'],
];

const link = (href, text) => h('a', { href, rel: 'noopener noreferrer' }, text);

export function renderFutures(ctx) {
  const requested = ctx.route.moment;
  const moment = MOMENTS.find((m) => m.id === requested) ?? MOMENTS[0];
  return h('section', { class: 'view', 'aria-labelledby': 'futures-title' },
    h('header', { class: 'view-head' },
      h('p', { class: 'eyebrow' }, 'A fictional day'),
      h('h1', { id: 'futures-title' }, 'A day we could make possible'),
      h('p', { class: 'lede' }, 'What if a good life were something we helped one another make possible, and everyone could help shape how?'),
      h('p', { class: 'note' }, 'An invented day to explore, change or reject. It illustrates a possibility, not a forecast or a capability this prototype already delivers.'),
    ),
    requested && requested !== moment.id ? routeNotice(requested) : null,
    h('nav', { 'aria-label': 'Moments in the day' }, h('ol', { class: 'tabs moments' }, MOMENTS.map((m) => h('li', null,
      h('a', { href: `#/futures/${m.id}`, 'aria-current': m.id === moment.id ? 'page' : null },
        h('span', { class: 'moment-time' }, m.time), ' ', m.title))))),
    momentCard(ctx, moment),
    wholeDay(),
    becomingReal(),
    sources(),
  );
}

function routeNotice(requested) {
  const earlier = EARLIER_MODEL_IDS.includes(requested);
  return h('p', { class: 'alert info' }, earlier
    ? 'This link pointed to an earlier comparison of three economic models. That comparison is no longer the starting point: this version begins with everyday life instead. The earlier text remains in the project’s git history, and posts that responded to it still show their label. Showing the first moment of the fictional day.'
    : 'There is no moment with that name. Showing the first moment of the fictional day.');
}

function momentCard(ctx, m) {
  const part = (key, title, body) => h('div', { class: `moment-part ${key}` }, h('h3', null, title), body);
  const respond = () => ctx.openPublish({
    roomId: 'future',
    draftKey: `respond-day:${m.id}`,
    title: 'Respond, or imagine it differently',
    intro: `About the fictional moment “${m.title}”. Say what you would keep, change or reject, or describe a different moment of your own. Nothing is filled in for you, and disagreeing is as useful as agreeing.`,
  });
  return h('article', { class: 'card moment', 'aria-labelledby': 'moment-title' },
    h('p', { class: 'eyebrow' }, m.time),
    h('h2', { id: 'moment-title' }, m.title),
    h('p', { class: 'day' }, m.scene),
    h('div', { class: 'moment-grid' },
      part('wants', 'What Maya wants to experience', h('p', null, m.wants)),
      part('barriers', 'What gets in the way today', h('p', null, m.barriers)),
      part('future', 'In this imagined future', h('p', null, m.future)),
      part('enabled', 'What made it possible', h('p', null, m.enabled)),
      part('experiment', 'A first experiment someone could try today', h('p', null, m.experiment)),
      part('open', 'Still unresolved', h('ul', null, m.open.map((q) => h('li', null, q)))),
    ),
    h('div', { class: 'row' },
      h('button', { type: 'button', class: 'primary', 'data-focus': `respond-day:${m.id}`, onClick: respond }, 'Respond, or imagine it differently'),
      h('a', { href: '#/talk' }, 'Talk through your own day privately with the AI interviewer')),
    h('p', { class: 'small muted' }, 'Responding publishes a post in a room you choose, after you review it. The private interview stays in your tab unless you choose to publish part of it.'),
  );
}

function wholeDay() {
  return h('section', { class: 'card quiet', 'aria-labelledby': 'whole-title' },
    h('h2', { id: 'whole-title' }, 'What sits underneath the whole day'),
    h('ul', { class: 'commitments' },
      h('li', null, h('strong', null, 'Access without an earnings test. '), 'In this scenario, food, a secure home, learning and essential support do not depend on a wage or a price. Over time some communities chose shared provision for essentials; others kept different arrangements while meeting the same guarantees. Early on, money and existing services still mattered, because they were real ways to help.'),
      h('li', null, h('strong', null, 'Coordination without one permanent centre. '), 'Neighbourhoods, resource networks and communities of knowledge make limited agreements they can revise. People who hold responsibilities for reliability, expertise, emergencies or disputes do so within limits, subject to review and replacement.'),
      h('li', null, h('strong', null, 'Limits and disagreement remain. '), 'Some things stay scarce: a particular place, another person’s time, ecological capacity. Someone is still responsible when things go wrong. When no arrangement suits everyone, the conflict stays visible and goes through an agreed process; nobody calls it consensus.'),
      h('li', null, h('strong', null, 'Nobody has to be useful. '), 'Maya could decline the path work. Nobody must be productive, cured, or on this platform to receive support. That evening her assistant offers to ask whether the day worked for her. She says “not now”, and it stops.'),
    ),
  );
}

function becomingReal() {
  const steps = [
    ['Personal accounts', 'people describe moments they want, in their own words.'],
    ['Confirmed purposes and barriers', 'each person confirms or corrects what their account means and what stands in the way.'],
    ['Alternatives and affected people', 'several possible arrangements are compared, with the people they would affect.'],
    ['Consented experiments', 'small trials that people choose to join, without losing their existing support.'],
    ['Lived outcomes', 'the people involved say whether their days changed, including any new burdens.'],
    ['Revise institutions, if needed', 'only then change larger arrangements, keeping what works.'],
  ];
  return h('section', { class: 'card', 'aria-labelledby': 'real-title' },
    h('h2', { id: 'real-title' }, 'How this could become real'),
    h('ol', { class: 'path' }, steps.map(([title, text]) => h('li', null, h('strong', null, title), `: ${text}`))),
    h('div', { class: 'model-grid' },
      h('div', null,
        h('h3', null, 'What this prototype does now'),
        h('ul', null,
          h('li', null, 'A private, opt-in AI interview about a day you would like to live.'),
          h('li', null, 'Public posts you review before publishing, and live replies.'),
          h('li', null, 'Common-ground statements that keep differences and concerns visible.'),
          h('li', null, 'Small actions that can state the everyday change they intend, with concerns that hold them until answered.'),
        )),
      h('div', null,
        h('h3', null, 'Proposed, not built'),
        h('ul', null,
          h('li', null, 'Matching people with resources, or allocating anything.'),
          h('li', null, 'Shared ownership of tools, spaces or automation.'),
          h('li', null, 'Health or care services of any kind.'),
          h('li', null, 'Federation between communities, or any governing authority.'),
          h('li', null, 'Measuring whether lives actually improved.'),
        )),
    ),
  );
}

function sources() {
  return h('section', { class: 'card quiet', 'aria-labelledby': 'sources-title' },
    h('h2', { id: 'sources-title' }, 'Ideas this draws on'),
    h('p', { class: 'small' }, 'Frameworks and proposals, not proof that this future works. None shows a successful society organised like this.'),
    h('ul', { class: 'commitments small' }, SOURCES.map(([href, text]) => h('li', null, link(href, text)))),
  );
}
